[IO.File]::WriteAllText((Join-Path $PWD 'settled.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# settled.sh LOG: waits until every exchange surl's log says was opened has ended, so the log holds the whole`n# of each one. It gives up after 5 seconds, leaving the log as it is.`ntries=0`nwhile [ `"`$(grep -c ' opened: ' `"`$1`")`" -gt `"`$(grep -c ' ended; ' `"`$1`")`" ] && [ `"`$tries`" -lt 25 ]; do`n  sleep 0.2`n  tries=`$((tries + 1))`ndone`n")
[IO.File]::WriteAllText((Join-Path $PWD 'who-stored.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# who-stored.sh LOG NAME: reads surl's verbose log and prints, for each upload of NAME the server completed,`n# the exchange it came in on and the account logged in there, then the account that stored it last.`n# An upload the server refused is left out. Exit 1 when the log shows no completed upload of NAME.`ntr -d '\r' < `"`$1`" | awk -v name=`"`$2`" '`n  { n = substr(`$1, 2) }`n  `$2 == `"*`" && `$3 == `"Login`" && `$4 == `"accepted:`" { who[n] = `$NF }`n  `$2 == `"<`" && `$0 == `"#`" n `" < STOR `" name `"\\r\\n`" { asked[n] = 1 }`n  `$2 == `">`" && asked[n] && `$3 ~ /^[2-5][0-9][0-9]`$/ {`n    if (`$3 ~ /^2/) { print `"exchange `" n `": `" who[n] `" stored `" name; last = who[n] }`n    asked[n] = 0`n  }`n  END {`n    if (last == `"`") { print `"no completed upload of `" name `" in the log`"; exit 1 }`n    print `"last stored by `" last`n  }'`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--user', 'alice:north-7', '--user', 'bob:south-9', '--allow-plaintext-auth', '--allow-uploads', '--max-filesize', '100', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
